function output=run_bdt_aware_active_gate_benchmark(outputDir)
% Compare BDT-aware layer-block proposals with matched cardinality controls.
narginchk(1,1);here=fileparts(mfilename('fullpath'));root=fileparts(fileparts(here));add_paths(root,here);create_empty(outputDir);
artifactFile=fullfile(root,'results','task25_27_pipeline_20deg.mat');stage1File=fullfile(root,'results','full_integrated_layer_20deg_job22180','alpha_0p3','alpha_0p3_final.mat');anchorFile=fullfile(root,'results','survivor_compression_boundary_job22813','survivor_compression_boundary_complete.mat');priorDir=fullfile(root,'results','adaptive_survivor_boundary_job22926');
source=load(artifactFile,'cfg','machine','dij','stf','pln','map');stage1=load(stage1File,'final','supportMask');anchorData=load(anchorFile,'output');anchorData=anchorData.output;a1=load(fullfile(priorDir,'attempt_01.mat'),'death');a2=load(fullfile(priorDir,'attempt_02.mat'),'death');patient=load(source.cfg.patientFile,'ct','cst');cfg=merge_structs(default_config(),source.cfg);
allowedFull=reshape(logical(stage1.supportMask),[],1);[dij,toFull,~,map]=reduce_dij_to_support(source.dij,allowedFull,source.map);for i=1:numel(map),map(i).originalGlobalIx=map(i).globalIx;map(i).globalIx=i;end;[groups,~]=build_group_index(map);[groupsFull,~]=build_group_index(source.map);D=nominal(dij);model=build_matrad_dose_model(dij,patient.cst,source.pln,0);wRef=reshape(double(stage1.final.w(toFull)),[],1);reference=evaluate_plan(wRef,model,D,patient,cfg,source,groupsFull,toFull,stage1.final.w);w=reshape(double(anchorData.w),[],1);anchor=evaluate_plan(w,model,D,patient,cfg,source,groupsFull,toFull,stage1.final.w);assert(anchor.activeSpots==133790&&clinical_state(anchor,reference).feasible);
settings=struct('shortlistLayers',24,'bdtTargets',[10 20],'maxProposalSpots',2400,'maxOuter',4,'activeMaxIter',80,'activeMaxCPU',120000,'zeroTolerance',1e-10);[~,g]=evaluate_matrad_dose_model(model,w,true);spec=build_clinical_gate_spec(D,patient.cst,reference.dose,2,.2);[~,gateJ]=evaluate_clinical_gates(D,w,spec,true);baseComp=component_values(model,D,w);
[layerScreen,shortlist]=screen_layers(w,g,gateJ,spec,groups,map,cfg,source,model,D,patient,groupsFull,toFull,stage1.final.w,anchor,baseComp,settings);writetable(layerScreen,fullfile(outputDir,'layer_screening.csv'));
proposals=repmat(struct('name','','kind','','death',[],'predictedBDTReduction',0,'predictedRepairCost',0),0,1);for i=1:numel(settings.bdtTargets),E=greedy_bdt_block(shortlist,layerScreen,groups,w,cfg,source,groupsFull,toFull,stage1.final.w,anchor.delivery.T_total,settings.bdtTargets(i),settings.maxProposalSpots);[dt,cr]=proposal_prediction(E,w,g,model,D,patient,cfg,source,groupsFull,toFull,stage1.final.w,anchor,baseComp,spec,gateJ);proposals(end+1)=struct('name',sprintf('bdt_aware_%gs',settings.bdtTargets(i)),'kind','BDT_AWARE','death',E,'predictedBDTReduction',dt,'predictedRepairCost',cr);end
master=unique([reshape(a1.death,[],1);reshape(a2.death,[],1)],'stable');for i=1:2,n=numel(proposals(i).death);E=master(1:min(n,numel(master)));[dt,cr]=proposal_prediction(E,w,g,model,D,patient,cfg,source,groupsFull,toFull,stage1.final.w,anchor,baseComp,spec,gateJ);proposals(end+1)=struct('name',sprintf('cardinality_control_%d',n),'kind','CARDINALITY_CONTROL','death',E,'predictedBDTReduction',dt,'predictedRepairCost',cr);end
rows=repmat(empty_result(),0,1);gateRows=repmat(empty_gate(),0,1);cgRows=repmat(empty_cg(),0,1);best=[];total=tic;
for p=1:numel(proposals),pr=proposals(p);support=w>settings.zeroTolerance;support(pr.death)=false;[dijR,r2f]=reduce_dij_to_support(dij,support);m=build_matrad_dose_model(dijR,patient.cst,source.pln,0);Dr=nominal(dijR);cgSet=struct('maxOuter',settings.maxOuter,'maxIter',settings.activeMaxIter,'maxCPU',settings.activeMaxCPU);cg=run_constraint_generation_repair(m,w(r2f),Dr,patient.cst,reference.dose,cgSet);wr=zeros(size(w));wr(r2f)=cg.w;plan=evaluate_plan(wr,model,D,patient,cfg,source,groupsFull,toFull,stage1.final.w);state=clinical_state(plan,reference);objectivePolicy=plan.objective<=1.02*reference.objective;dominatedRegression=plan.objective>anchor.objective&&plan.delivery.T_total>anchor.delivery.T_total;algorithmAccepted=state.feasible&&objectivePolicy&&plan.activeSpots<anchor.activeSpots&&~dominatedRegression;paretoImproving=state.feasible&&plan.activeSpots<anchor.activeSpots&&plan.objective<=anchor.objective&&plan.delivery.T_total<=anchor.delivery.T_total;realizedBDT=anchor.delivery.T_total-plan.delivery.T_total;actualRepair=max(0,plan.objective-anchor.objective)/max(1,abs(anchor.objective));rows(end+1)=result_row(p,pr,plan,state,objectivePolicy,algorithmAccepted,paretoImproving,dominatedRegression,realizedBDT,actualRepair,cg,toc(total));gateRows=[gateRows;gate_rows(p,pr.name,plan,reference)];cgRows=[cgRows;cg_rows(p,pr.name,cg.history)];save(fullfile(outputDir,sprintf('proposal_%02d.mat',p)),'pr','support','cg','wr','plan','state','objectivePolicy','algorithmAccepted','paretoImproving','-v7.3');flush(outputDir,rows,gateRows,cgRows);fprintf('BDT_PROPOSAL %s deaths=%d predT=%.3f realT=%.3f cost=%.6g obj=%.6f gates=%d accept=%d iters=%d outer=%d\n',pr.name,numel(pr.death),pr.predictedBDTReduction,realizedBDT,pr.predictedRepairCost,plan.objective,state.feasible,algorithmAccepted,sum([cg.history.iterations]),cg.outerIterations);if algorithmAccepted&&(isempty(best)||plan.delivery.T_total<best.plan.delivery.T_total),best=struct('proposal',pr,'plan',plan,'w',wr,'row',rows(end));end,end
strictPareto=any([rows.paretoImproving]);if isempty(best),incumbentW=w;incumbent=anchor;selectionLabel='NO_NONDOMINATED_TRANSITION_ACCEPTED';else,incumbentW=best.w;incumbent=best.plan;selectionLabel='NONDOMINATED_TRANSITION_SELECTED';end;if strictPareto,paretoLabel='PARETO_IMPROVING_TRANSITION_FOUND';else,paretoLabel='NO_PARETO_IMPROVEMENT';end
predT=[rows.predictedBDTReduction]';realT=[rows.realizedBDTReduction]';predC=[rows.predictedRepairCost]';realC=[rows.actualRepairCost]';corrT=safe_corr(predT,realT);corrC=safe_corr(predC,realC);benchmark=struct('job23056Iterations',0,'job23056SolverWallSeconds',3182.070439,'activeGateMedianIterations',median([rows.ipoptIterations]),'activeGateMedianWallSeconds',median([rows.solverWallSeconds]),'corrPredictedRealizedBDT',corrT,'corrPredictedActualRepairCost',corrC);
output=struct('paretoLabel',paretoLabel,'selectionLabel',selectionLabel,'anchor',anchor,'incumbent',incumbent,'incumbentW',incumbentW,'proposals',proposals,'rows',rows,'gateRows',gateRows,'constraintGeneration',cgRows,'benchmark',benchmark,'wallSeconds',toc(total));save(fullfile(outputDir,'bdt_aware_active_gate_complete.mat'),'output','-v7.3');flush(outputDir,rows,gateRows,cgRows);write_report(outputDir,output);fprintf('FINAL_STATUS: %s / %s corrT=%.4f corrC=%.4f\n',paretoLabel,selectionLabel,corrT,corrC);
end

function [T,short]=screen_layers(w,g,J,spec,groups,map,cfg,source,model,D,patient,groupsFull,toFull,wTemplate,anchor,baseComp,s)
n=numel(groups);id=(1:n)';spots=zeros(n,1);weight=zeros(n,1);predT=zeros(n,1);first=zeros(n,1);target=zeros(n,1);approx=zeros(n,1);for k=1:n,E=groups(k).ix;E=E(w(E)>s.zeroTolerance);spots(k)=numel(E);weight(k)=sum(w(E));if isempty(E),continue;end;z=w;z(E)=0;full=embed(z,toFull,wTemplate);del=compute_delivery_metrics(full,source.map,groupsFull,cfg,source.machine);predT(k)=anchor.delivery.T_total-del.T_total;first(k)=max(0,-sum(g(E).*w(E)));for q=1:numel(spec),if strcmp(spec(q).sense,'lower'),target(k)=target(k)+sum(abs(J(q,E).*w(E)'));end,end;approx(k)=first(k)/max(1,anchor.objective)+target(k);end
score=predT./max(approx,1e-10);[~,o]=sort(score,'descend');short=o(1:min(s.shortlistLayers,numel(o)));finiteDelta=nan(n,1);componentCost=nan(n,1);curvature=nan(n,1);exactCost=inf(n,1);for k=reshape(short,1,[]),E=groups(k).ix;E=E(w(E)>s.zeroTolerance);z=w;z(E)=0;f=evaluate_matrad_dose_model(model,z,false);finiteDelta(k)=f-anchor.objective;c=component_values(model,D,z);componentCost(k)=sum(max(0,(c-baseComp)./max(1,abs(baseComp))));linear=-sum(g(E).*w(E));curvature(k)=max(0,finiteDelta(k)-linear);exactCost(k)=max(0,finiteDelta(k))/max(1,anchor.objective)+componentCost(k)+curvature(k)/max(1,anchor.objective)+target(k);end;exactScore=predT./max(exactCost,1e-10);cp=zeros(n,1);energy=zeros(n,1);for k=1:n,ix=groups(k).ix;if ~isempty(ix),cp(k)=map(ix(1)).cpIndex;energy(k)=map(ix(1)).energy;end,end;T=table(id,cp,energy,spots,weight,predT,first,target,approx,finiteDelta,componentCost,curvature,exactCost,exactScore);end
function E=greedy_bdt_block(short,T,groups,w,cfg,source,groupsFull,toFull,wTemplate,baseBDT,target,maxSpots),[~,o]=sort(T.exactScore(short),'descend');order=short(o);E=[];
for k=reshape(order,1,[]),cand=unique([E;groups(k).ix(w(groups(k).ix)>1e-10)]);if numel(cand)>maxSpots,continue;end;E=cand;z=w;z(E)=0;delivery=compute_delivery_metrics(embed(z,toFull,wTemplate),source.map,groupsFull,cfg,source.machine);if baseBDT-delivery.T_total>=target,break;end;end
if isempty(E),E=groups(order(1)).ix(w(groups(order(1)).ix)>1e-10);end
end
function [dt,cost]=proposal_prediction(E,w,g,model,D,patient,cfg,source,groupsFull,toFull,wTemplate,anchor,baseComp,spec,J),z=w;z(E)=0;plan=evaluate_plan(z,model,D,patient,cfg,source,groupsFull,toFull,wTemplate);dt=anchor.delivery.T_total-plan.delivery.T_total;fdelta=plan.objective-anchor.objective;linear=-sum(g(E).*w(E));curv=max(0,fdelta-linear);comp=component_values(model,D,z);cc=sum(max(0,(comp-baseComp)./max(1,abs(baseComp))));target=0;for q=1:numel(spec),if strcmp(spec(q).sense,'lower'),target=target+sum(abs(J(q,E).*w(E)'));end,end;cost=max(0,fdelta)/max(1,anchor.objective)+curv/max(1,anchor.objective)+cc+target;end
function v=component_values(model,D,w),x=D*w;v=[];for i=1:size(model.cst,1),vox=reshape(double(model.cst{i,4}{1}),[],1);for j=1:numel(model.cst{i,6}),o=model.cst{i,6}{j};if ~isa(o,'DoseObjectives.matRad_DoseObjective'),continue;end;o=model.optiProb.BP.setBiologicalDosePrescriptions(o,model.cst{i,5}.alphaX,model.cst{i,5}.betaX);v(end+1,1)=double(o.penalty*o.computeDoseObjectiveFunction(x(vox)));end,end;end
function full=embed(w,toFull,template),full=zeros(size(template));full(toFull)=w;end
function p=evaluate_plan(w,model,D,patient,cfg,source,groupsFull,toFull,wTemplate),[f,~,d]=evaluate_matrad_dose_model(model,w,false);z=embed(w,toFull,wTemplate);p=struct('objective',f,'maxConstraintViolation',d.maxConstraintViolation,'dose',compute_dvh_metrics(full(D*w),patient.ct,patient.cst,cfg),'delivery',compute_delivery_metrics(z,source.map,groupsFull,cfg,source.machine),'activeSpots',nnz(w>1e-10),'activeLayers',count_layers(w,build_groups(source.map,toFull),1e-10));end
function s=clinical_state(p,r),[pass,worst,detail]=dose_quality(p.dose,r.dose);s=struct('feasible',pass&&p.maxConstraintViolation<=1e-6,'dosePass',pass,'constraintPass',p.maxConstraintViolation<=1e-6,'worstAdverse',worst,'detail',{detail});end
function [pass,worst,rows]=dose_quality(c,r),pass=true;worst=0;rows={};for i=1:numel(c.structures),a=r.structures(i);b=c.structures(i);if a.isTarget,keys={'D95','D98'};sense='lower';elseif strcmpi(a.type,'OAR')&&~ismember(upper(a.name),{'BODY','EXTERNAL'}),keys={'Dmean','Dmax'};sense='upper';else,continue;end;for k=1:numel(keys),m=keys{k};if strcmp(sense,'lower'),lim=.98*a.(m);ok=b.(m)>=lim;adv=max(0,100*(a.(m)-b.(m))/max(abs(a.(m)),eps));else,lim=a.(m)+max(.2,.02*max(abs(a.(m)),1));ok=b.(m)<=lim;adv=max(0,100*(b.(m)-a.(m))/max(abs(a.(m)),eps));end;rows(end+1,:)={a.name,m,b.(m),lim,ok};pass=pass&&ok;worst=max(worst,adv);end,end,end
function r=empty_result(),r=struct('proposal',0,'name','','kind','','proposedDeaths',0,'predictedBDTReduction',0,'realizedBDTReduction',0,'predictedRepairCost',0,'actualRepairCost',0,'sameEventReturns',0,'historicalDormantBirths',0,'permanentDeaths',0,'activeSpots',0,'activeLayers',0,'objective',0,'bdt',0,'clinicallyFeasible',false,'objectivePolicy',false,'paretoDominatedRegression',false,'paretoImproving',false,'algorithmicallyAccepted',false,'cgIterations',0,'exactGateEvaluations',0,'ipoptIterations',0,'primalInfeasibility',0,'dualInfeasibility',0,'solverWallSeconds',0,'totalWallSeconds',0);end
function r=result_row(i,p,plan,state,op,aa,pi,dom,realT,realC,cg,wall),r=empty_result();r.proposal=i;r.name=p.name;r.kind=p.kind;r.proposedDeaths=numel(p.death);r.predictedBDTReduction=p.predictedBDTReduction;r.realizedBDTReduction=realT;r.predictedRepairCost=p.predictedRepairCost;r.actualRepairCost=realC;r.permanentDeaths=numel(p.death);r.activeSpots=plan.activeSpots;r.activeLayers=plan.activeLayers;r.objective=plan.objective;r.bdt=plan.delivery.T_total;r.clinicallyFeasible=state.feasible;r.objectivePolicy=op;r.paretoDominatedRegression=dom;r.paretoImproving=pi;r.algorithmicallyAccepted=aa;r.cgIterations=cg.outerIterations;r.exactGateEvaluations=cg.exactGateEvaluations;r.ipoptIterations=sum([cg.history.iterations]);r.primalInfeasibility=cg.lastSolver.primalInfeasibility;r.dualInfeasibility=cg.lastSolver.dualInfeasibility;r.solverWallSeconds=sum([cg.history.solverWallSeconds]);r.totalWallSeconds=wall;end
function r=empty_gate(),r=struct('proposal',0,'name','','structure','','metric','','value',0,'limit',0,'pass',false);end
function r=gate_rows(k,name,p,ref),[~,~,d]=dose_quality(p.dose,ref.dose);r=repmat(empty_gate(),size(d,1),1);for i=1:size(d,1),r(i)=struct('proposal',k,'name',name,'structure',d{i,1},'metric',d{i,2},'value',d{i,3},'limit',d{i,4},'pass',d{i,5});end,end
function r=empty_cg(),r=struct('proposal',0,'name','','outer',0,'activeRows',0,'newRows',0,'exactGatePass',false,'objective',0,'iterations',0,'primalInfeasibility',0,'dualInfeasibility',0,'solverWallSeconds',0);end
function r=cg_rows(k,name,h),r=repmat(empty_cg(),numel(h),1);for i=1:numel(h),r(i)=struct('proposal',k,'name',name,'outer',h(i).outer,'activeRows',h(i).activeRows,'newRows',h(i).newRows,'exactGatePass',h(i).exactGatePass,'objective',h(i).objective,'iterations',h(i).iterations,'primalInfeasibility',h(i).primalInfeasibility,'dualInfeasibility',h(i).dualInfeasibility,'solverWallSeconds',h(i).solverWallSeconds);end,end
function flush(o,a,b,c),if ~isempty(a),writetable(struct2table(a,'AsArray',true),fullfile(o,'proposal_results.csv'));end;if ~isempty(b),writetable(struct2table(b,'AsArray',true),fullfile(o,'clinical_gate_results.csv'));end;if ~isempty(c),writetable(struct2table(c,'AsArray',true),fullfile(o,'constraint_generation_history.csv'));end,end
function write_report(o,x),f=fopen(fullfile(o,'BDT_AWARE_ACTIVE_GATE_REPORT.md'),'w');c=onCleanup(@()fclose(f));fprintf(f,'# BDT-aware support search with active gates\n\nPareto status: `%s`\n\nIncumbent-selection status: `%s`\n\nPredicted/realized BDT correlation: %.6g. Predicted/actual repair-cost correlation: %.6g. These correlations use only the bounded proposal set and are diagnostic, not inferential.\n\nSelected incumbent spots/layers: %d/%d; objective %.9g; BDT %.3f s.\n',x.paretoLabel,x.selectionLabel,x.benchmark.corrPredictedRealizedBDT,x.benchmark.corrPredictedActualRepairCost,x.incumbent.activeSpots,x.incumbent.activeLayers,x.incumbent.objective,x.incumbent.delivery.T_total);end
function c=safe_corr(a,b),if numel(a)<2||std(a)==0||std(b)==0,c=NaN;else,q=corrcoef(a,b);c=q(1,2);end,end
function D=nominal(d),D=d.physicalDose;if iscell(D),D=D{1};end,end
function g=build_groups(map,toFull),m=map(toFull);for i=1:numel(m),m(i).globalIx=i;end;g=build_group_index(m);end
function n=count_layers(w,g,t),n=0;for i=1:numel(g),n=n+any(w(g(i).ix)>t);end,end
function add_paths(root,here),f={'config','planning','mapping','objective','delivery','reduction','evaluation','integrated','robustness'};for i=1:numel(f),addpath(fullfile(root,f{i}));end;addpath(fullfile(root,'experiments','repeated_dormant_replacement'));addpath(here);end
function create_empty(d),if exist(d,'dir')==7,e=dir(d);e=e(~ismember({e.name},{'.','..'}));assert(isempty(e));else,mkdir(d);end,end
function m=merge_structs(a,b),m=a;f=fieldnames(b);for i=1:numel(f),k=f{i};if isfield(m,k)&&isstruct(m.(k))&&isstruct(b.(k)),m.(k)=merge_structs(m.(k),b.(k));else,m.(k)=b.(k);end,end,end
